"""Record the exact Alpha 1.0 artifact and native regression evidence."""
from pathlib import Path
import json,hashlib
root=Path(__file__).resolve().parents[2];base=root/'output/elyndor/pixellab-v21'
def read(name):return json.loads((base/name).read_text(encoding='utf-8'))
a=json.loads((root/'output/elyndor/continuous-standalone-audit.json').read_text());reg=read('regression.json');new=read('revision/report.json');records=read('records/report.json');stairs=read('stairs/report.json');coached=read('coached/report.json');campaign=read('campaign/report.json');performance=read('performance/native.json');combat=read('combat-profile-final.json');atlas=read('atlas-performance.json');voices=read('audio-audit.json');sounds=read('soundtrack-audit.json');water=read('water/report.json');locations=read('locations/report.json');macro=read('overworld/report.json');dry=read('soak-release-dry.json');storm=read('soak-release-storm.json')
sha=hashlib.sha256((root/'index.html').read_bytes()).hexdigest()
assert sha==reg['sha256']==a['sha256'] and a['sourceMatchesArtifact'] and not a['cropWarnings']
assert len(reg['checks'])==31 and all(q['pass']for q in reg['checks'])
assert all(q['pass']for q in [new,records,stairs,coached,atlas,voices,sounds,water,locations,macro,dry,storm])
assert campaign['campaign']['final']=='complete' and not campaign['errors'] and not campaign['voiceMissing']
assert performance['pass']
assert not combat['newPrograms'] and combat['cpu']['p95']<25
pump=read('pump-fixed.json');assert not pump['errors'] and not pump['newPrograms'] and pump['tick']['p95']<10 and pump['tick']['max']<50
text=(root/'elyndor/title-v19.js').read_text(encoding='utf-8');catalog=json.loads(text.split('const CHANGELOG19=',1)[1].split(';\n',1)[0]);assert len(catalog)==1 and catalog[0]['version']=='Alpha Version 1.0'
transcripts=json.loads((root/'elyndor/audio/transcription-audit-v18.json').read_text());assert transcripts['clips']==10 and not transcripts['unresolvedWordDifferences']
r={'release':'elyndor-alpha-1.0-2026-10-29-v21','version':'Alpha Version 1.0','game':'The Last Light of Elyndor','artifact':{'file':'index.html','bytes':a['bytes'],'sha256':sha,'offline':True},
 'featureCatalogue':catalog[0],
 'githubHistory':{'firstCommit':'8a061609410b54af58775c8bbeaab15981a55acc','firstDate':'2026-10-22','previousRelease':'89cf8ad8e28e7590e03ff72947cb447041cc58a6'},
 'changes':['One Alpha Version 1.0 catalogue replaces all incremental changelog entries, with current systems and history from the first GitHub build','Balanced reflections draw one visible pool per frame and high quality draws two; small foliage, precipitation and transient effects are excluded from reflection views','River state remains continuous; geometry is deferred to the next draw, and stable monitor pacing avoids duplicate simulation work after late frames','Overworld vegetation uses padded spatial branches for main, reflection and shadow views; cached static transforms and a single quality budget eliminate redundant matrix work and shadow-target reallocation',
 'Music and environmental stream containers are prepared under the loader with a typed byte loop, removing first-theme-change decoding stalls','Enemy shadow geometry is released at battlefield restoration; scene foliage LOD masks and obsolete renderer lists are disposed with their owners','One recorded speech queue serializes narration, story lines and battle calls; story advances wait for the current spoken line','Projected per-instance color masks keep foreground vegetation off every fighter while preserving shadows and restoring scenery afterwards, including LOD changes','All outdoor locations and the overworld receive a broad, continuously shaded overhead cloud field with coordinated soft moving shadows','Element-specific pooled weapon ribbons, fire coils, ice shards, arcane columns, smoke, sparks, wards and Ascension effects reuse approved textures and dynamic lighting'],
 'art':{'generator':'PixelLab','nativeSelectedFamilies':41,'runtimeFamilies':42,'packedSpritePoses':a['packedPoses'],'sourceCropWarnings':0,'newGeneratedAssets':0,'materialSize':[512,512],'rejectedCandidatesExcluded':True},
 'audio':{'provider':'ElevenLabs','recordedVoices':voices['clips'],'soundAssets':sounds['sounds'],'newGeneratedAssets':0,'offline':True,'embeddedCredential':False,'transcription':transcripts,'serializedSpeech':new['speech'],'queuedStory':new['speechQueued']},
 'validation':{'checks':reg['checks'],'alphaCloudVisibilityEffectsAndSpeech':new,'titleAndRecords':records,'stairAndRiverRepairs':stairs,'keyboardStairCrossings':len(stairs['walks']),'stairEdgeSamples':sum(q['count']for q in stairs['edges']),'coachedBattleRegression':coached,'locations':locations,'sourceMatchesArtifact':True,'storyProgressionSteps':len(campaign['campaign']['log']),'storyBattles':len(campaign['campaign']['battles']),'restoredLights':len(campaign['campaign']['restored']),'saveLoad':campaign['persistence'],'waterJoinMaxGapMetres':max(j['gap']for row in coached['water']for j in row['joins']),'overworldApproaches':macro},
 'performance':{'device':performance['device'],'overworldBaseline':read('overworld-baseline.json'),'nativeScenarios':performance['scenarios'],'repeatedDryPlay':dry,'repeatedStormPlay':storm,'pump':pump,'tutorial':read('onboarding-performance.json'),'combatRenderCPU':combat['cpu'],'newCombatPrograms':len(combat['newPrograms']),'atlas':atlas,'scope':'Native Chrome at 1440x900 on the recorded RTX 4080 device. Draw target follows monitor cadence (about 72 Hz here). Tests include repeated travel, filling river, full storm and twenty simultaneous spell effects. Retained heap uses test-only forced GC; runtime does not. Performance varies by hardware.'}}
(root/'release.json').write_text(json.dumps(r,indent=2,ensure_ascii=False)+'\n',encoding='utf-8');print(json.dumps({'release':r['release'],'bytes':a['bytes'],'sha256':sha,'checks':len(reg['checks']),'audioAssets':voices['clips']+sounds['sounds']}))
